export const SCHEMA_SQL = "-- Smart Parking: PostgreSQL tables, v2 (floors + B/C slot names).\n-- Safe to run every time: it never drops anything. On an old v1 database, run migrate_v2_floors.sql after it\n-- (the app does both automatically on its first request, see lib/setup.js).\n-- Times are TIMESTAMPTZ; compare with NOW(), display in Asia/Kolkata.\n\nCREATE TABLE IF NOT EXISTS app_meta (\n  key   VARCHAR(50) PRIMARY KEY,\n  value VARCHAR(100) NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS users (\n  id            SERIAL PRIMARY KEY,\n  name          VARCHAR(100) NOT NULL,\n  email         VARCHAR(150) NOT NULL UNIQUE,\n  phone         VARCHAR(15),\n  password_hash VARCHAR(255) NOT NULL,                 -- bcryptjs hash\n  role          VARCHAR(10)  NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')),\n  created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS parking_locations (\n  id             SERIAL PRIMARY KEY,\n  name           VARCHAR(100) NOT NULL,\n  address        VARCHAR(255),\n  latitude       NUMERIC(10,7) NOT NULL,\n  longitude      NUMERIC(10,7) NOT NULL,\n  price_per_hour NUMERIC(8,2)  NOT NULL DEFAULT 20.00,\n  created_at     TIMESTAMPTZ   NOT NULL DEFAULT NOW()\n);\n\n-- A slot = lot + floor + vehicle type + number. The label (e.g. F1-B12) is a generated column\n-- built from those three, so it can never disagree with them.\n--   floor:        LG = lower ground, G = ground, F1 / F2 / F3 = floors 1-3\n--   vehicle_type: B = bike (any two-wheeler), C = car (any four-wheeler)\nCREATE TABLE IF NOT EXISTS slots (\n  id           SERIAL PRIMARY KEY,\n  location_id  INT NOT NULL REFERENCES parking_locations(id) ON DELETE CASCADE,\n  floor        VARCHAR(2) NOT NULL DEFAULT 'G' CONSTRAINT chk_slot_floor CHECK (floor IN ('LG','G','F1','F2','F3')),\n  vehicle_type CHAR(1)    NOT NULL DEFAULT 'C' CONSTRAINT chk_slot_type CHECK (vehicle_type IN ('B','C')),\n  slot_no      SMALLINT   NOT NULL CONSTRAINT chk_slot_no CHECK (slot_no BETWEEN 1 AND 99),\n  slot_label   VARCHAR(8) GENERATED ALWAYS AS (floor || '-' || vehicle_type || lpad(slot_no::text, 2, '0')) STORED,\n  is_active    BOOLEAN NOT NULL DEFAULT TRUE,            -- admin can disable a slot\n  CONSTRAINT uq_slot UNIQUE (location_id, floor, vehicle_type, slot_no)\n);\n\nCREATE TABLE IF NOT EXISTS bookings (\n  id             SERIAL PRIMARY KEY,\n  user_id        INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  slot_id        INT NOT NULL REFERENCES slots(id) ON DELETE CASCADE,\n  vehicle_number VARCHAR(20) NOT NULL,\n  start_time     TIMESTAMPTZ NOT NULL,\n  end_time       TIMESTAMPTZ NOT NULL,\n  amount         NUMERIC(8,2) NOT NULL DEFAULT 0,\n  status         VARCHAR(10) NOT NULL DEFAULT 'booked'\n                 CHECK (status IN ('booked','cancelled','entered','completed')),\n  payment_status VARCHAR(10) NOT NULL DEFAULT 'pending' CHECK (payment_status IN ('pending','paid')),\n  payment_ref    VARCHAR(100),\n  paid_at        TIMESTAMPTZ,\n  qr_token       VARCHAR(64) UNIQUE,\n  exit_otp_hash  VARCHAR(255),\n  otp_expires_at TIMESTAMPTZ,\n  entry_time     TIMESTAMPTZ,\n  exit_time      TIMESTAMPTZ,\n  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  CHECK (end_time > start_time)\n);\nCREATE INDEX IF NOT EXISTS idx_slot_time ON bookings (slot_id, start_time, end_time);\n-- Overlap check (in the API): a slot is taken if a row exists with\n-- slot_id = $1 AND status IN ('booked','entered') AND start_time < $newEnd AND end_time > $newStart\n";
export const MIGRATE_SQL = "-- Smart Parking: upgrade an existing database to v2 (floors LG/G/F1/F2/F3 + B/C slot names).\n-- Idempotent: safe to run any number of times, and a no-op on a database that is already v2.\n-- Run it after schema.sql. The app runs both automatically on its first request (lib/setup.js).\n--\n-- What it does to an old (v1) database:\n--   1. copies the old slots and bookings tables to slots_v1_backup / bookings_v1_backup (once)\n--   2. vehicle_type 'car' / 'bike' becomes 'C' / 'B'\n--   3. each old slot (A1, A2, B1 ...) moves to the Ground floor and keeps its number per type,\n--      so A3 (car) becomes G-C03 and B2 (bike) becomes G-B02. Slot ids do not change, so every booking is kept.\n--   4. the old slot_number column is removed and each lot's ground-floor layout is copied to LG, F1, F2 and F3\n--   5. adds bookings.paid_at and the v2 constraints and indexes\n\nCREATE TABLE IF NOT EXISTS app_meta (key VARCHAR(50) PRIMARY KEY, value VARCHAR(100) NOT NULL);\n\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.columns\n             WHERE table_schema = current_schema() AND table_name = 'slots' AND column_name = 'slot_number') THEN\n    IF to_regclass('slots_v1_backup') IS NULL THEN\n      CREATE TABLE slots_v1_backup AS SELECT * FROM slots;\n    END IF;\n    IF to_regclass('bookings_v1_backup') IS NULL THEN\n      CREATE TABLE bookings_v1_backup AS SELECT * FROM bookings;\n    END IF;\n\n    ALTER TABLE slots DROP CONSTRAINT IF EXISTS slots_vehicle_type_check;\n    ALTER TABLE slots ALTER COLUMN vehicle_type DROP DEFAULT;\n    UPDATE slots SET vehicle_type = CASE WHEN lower(trim(vehicle_type)) IN ('bike', 'b') THEN 'B' ELSE 'C' END;\n    ALTER TABLE slots ALTER COLUMN vehicle_type TYPE CHAR(1);\n\n    ALTER TABLE slots ADD COLUMN IF NOT EXISTS floor VARCHAR(2);\n    ALTER TABLE slots ADD COLUMN IF NOT EXISTS slot_no SMALLINT;\n    -- Number slots 1, 2, 3 ... per lot and type, in the order of their old number (A1, A2 ... / B1, B2 ...).\n    -- More than 99 of one type in one lot spill over to the next floor so every number stays 2 digits.\n    UPDATE slots s\n       SET floor   = (ARRAY['G','F1','F2','F3','LG'])[LEAST(5, (n.rn - 1) / 99 + 1)],\n           slot_no = (n.rn - 1) % 99 + 1\n      FROM (SELECT id, ROW_NUMBER() OVER (\n                     PARTITION BY location_id, vehicle_type\n                     ORDER BY NULLIF(regexp_replace(slot_number, '[^0-9]', '', 'g'), '')::int NULLS LAST, slot_number, id) AS rn\n              FROM slots) n\n     WHERE n.id = s.id;\n\n    ALTER TABLE slots DROP CONSTRAINT IF EXISTS slots_location_id_slot_number_key;\n    ALTER TABLE slots DROP COLUMN slot_number;\n\n    -- Every lot gets all five floors: copy the ground-floor layout to LG, F1, F2 and F3\n    INSERT INTO slots (location_id, floor, vehicle_type, slot_no, is_active)\n    SELECT s.location_id, f.floor, s.vehicle_type, s.slot_no, s.is_active\n      FROM slots s CROSS JOIN (VALUES ('LG'), ('F1'), ('F2'), ('F3')) AS f(floor)\n     WHERE s.floor = 'G'\n       AND NOT EXISTS (SELECT 1 FROM slots x WHERE x.location_id = s.location_id AND x.floor = f.floor\n                         AND x.vehicle_type = s.vehicle_type AND x.slot_no = s.slot_no);\n  END IF;\nEND $$;\n\n-- v2 rules (no-ops when they already exist)\nALTER TABLE slots ALTER COLUMN floor SET DEFAULT 'G';\nALTER TABLE slots ALTER COLUMN floor SET NOT NULL;\nALTER TABLE slots ALTER COLUMN vehicle_type SET DEFAULT 'C';\nALTER TABLE slots ALTER COLUMN slot_no SET NOT NULL;\nALTER TABLE slots ADD COLUMN IF NOT EXISTS slot_label VARCHAR(8)\n  GENERATED ALWAYS AS (floor || '-' || vehicle_type || lpad(slot_no::text, 2, '0')) STORED;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'slots'::regclass AND conname = 'chk_slot_floor') THEN\n    ALTER TABLE slots ADD CONSTRAINT chk_slot_floor CHECK (floor IN ('LG','G','F1','F2','F3'));\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'slots'::regclass AND conname = 'chk_slot_type') THEN\n    ALTER TABLE slots ADD CONSTRAINT chk_slot_type CHECK (vehicle_type IN ('B','C'));\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'slots'::regclass AND conname = 'chk_slot_no') THEN\n    ALTER TABLE slots ADD CONSTRAINT chk_slot_no CHECK (slot_no BETWEEN 1 AND 99);\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'slots'::regclass AND conname = 'uq_slot') THEN\n    ALTER TABLE slots ADD CONSTRAINT uq_slot UNIQUE (location_id, floor, vehicle_type, slot_no);\n  END IF;\nEND $$;\n\nALTER TABLE bookings ADD COLUMN IF NOT EXISTS paid_at TIMESTAMPTZ;\nCREATE INDEX IF NOT EXISTS idx_slot_location ON slots (location_id);\nCREATE INDEX IF NOT EXISTS idx_booking_start ON bookings (start_time);\n\nINSERT INTO app_meta (key, value) VALUES ('schema_version', '2')\nON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;\n";
export const SEED_SQL = "-- Demo data (v2). The app runs this only when the users table is empty.\n-- seed_demo_v3.sql runs right after it and sets the real passwords (documented privately, not in this repo).\nINSERT INTO users (name,email,phone,password_hash,role) VALUES\n('Admin','admin@parking.com','9000000000','$2a$10$PQS.zOY51K8yV.oJMz4VauV7xDFpgKMYCaqvHqnwZfGlt3LiZ9JsW','admin'),\n('Rahul Patil','rahul@example.com','9000000001','$2a$10$Qyo7uLH8p02DMy91ATBK6OtcOFXhF9Dnnrxv8cN2q7jL6DW.xC2uC','user'),\n('Sneha Kulkarni','sneha@example.com','9000000002','$2a$10$Qyo7uLH8p02DMy91ATBK6OtcOFXhF9Dnnrxv8cN2q7jL6DW.xC2uC','user'),\n('Arjun Desai','arjun@example.com','9000000003','$2a$10$Qyo7uLH8p02DMy91ATBK6OtcOFXhF9Dnnrxv8cN2q7jL6DW.xC2uC','user');\n\nINSERT INTO parking_locations (name,address,latitude,longitude,price_per_hour) VALUES\n('Central Bus Stand Parking','CBT, Belagavi',15.8650,74.5120,20.00),\n('Belagavi Railway Station Parking','Station Road, Belagavi',15.8527,74.5030,25.00),\n('KLS GIT Campus Parking','Udyambag, Belagavi',15.8195,74.4880,10.00),\n('Khade Bazar Parking','Khade Bazar, Belagavi',15.8600,74.5160,30.00);\n\n-- Every lot has all five floors. Per floor: CBT 6 bikes + 4 cars, Railway 8 + 5, KLS GIT 6 + 3, Khade Bazar 6 + 4 (210 slots)\nINSERT INTO slots (location_id, floor, vehicle_type, slot_no)\nSELECT l.id, f.floor, t.vt, n\n  FROM (VALUES ('Central Bus Stand Parking', 6, 4), ('Belagavi Railway Station Parking', 8, 5),\n               ('KLS GIT Campus Parking', 6, 3), ('Khade Bazar Parking', 6, 4)) AS c(name, bikes, cars)\n  JOIN parking_locations l ON l.name = c.name\n CROSS JOIN (VALUES ('LG', 1), ('G', 2), ('F1', 3), ('F2', 4), ('F3', 5)) AS f(floor, ord)\n CROSS JOIN (VALUES ('B'), ('C')) AS t(vt)\n CROSS JOIN LATERAL generate_series(1, CASE WHEN t.vt = 'B' THEN c.bikes ELSE c.cars END) AS n\n ORDER BY l.id, f.ord, t.vt, n;\n\n-- Sample bookings: a few active now (taken slots on the map), one tomorrow, and two weeks of history for the admin report\nINSERT INTO bookings (user_id, slot_id, vehicle_number, start_time, end_time, amount, status, payment_status, payment_ref,\n                      paid_at, qr_token, entry_time, exit_time, created_at)\nSELECT u.id, s.id, v.veh, v.st, v.st + v.hrs * interval '1 hour', v.amt, v.status, v.pay, v.ref,\n       CASE WHEN v.pay = 'paid' THEN LEAST(v.st - interval '110 minutes', NOW()) END,\n       md5('seed-' || v.n),\n       CASE WHEN v.status IN ('entered', 'completed') THEN v.st + interval '5 minutes' END,\n       CASE WHEN v.status = 'completed' THEN v.st + v.hrs * interval '1 hour' - interval '10 minutes' END,\n       LEAST(v.st - interval '2 hours', NOW())\n  FROM (VALUES\n    (1,  'rahul@example.com', 'Central Bus Stand Parking',        'G',  'C', 1, 'KA22AB1234', (NOW() - interval '1 hour')::timestamptz,              3,  60, 'booked',    'paid',    'MOCKSEED0001'),\n    (2,  'sneha@example.com', 'Belagavi Railway Station Parking', 'F1', 'C', 2, 'KA22CD5678', NOW()::timestamptz,                                    3,  75, 'booked',    'pending', NULL),\n    (3,  'arjun@example.com', 'Central Bus Stand Parking',        'LG', 'B', 2, 'KA22EJ4321', (NOW() - interval '30 minutes')::timestamptz,          2,  40, 'entered',   'paid',    'MOCKSEED0003'),\n    (4,  'sneha@example.com', 'Khade Bazar Parking',              'F1', 'C', 4, 'KA22CD5678', ((CURRENT_DATE + 1) + time '10:00')::timestamptz,      2,  60, 'booked',    'paid',    'MOCKSEED0004'),\n    (5,  'rahul@example.com', 'KLS GIT Campus Parking',           'G',  'B', 2, 'KA22EF1111', ((CURRENT_DATE - 1) + time '09:00')::timestamptz,      6,  60, 'completed', 'paid',    'MOCKSEED0005'),\n    (6,  'rahul@example.com', 'Belagavi Railway Station Parking', 'LG', 'B', 3, 'KA22EF1111', ((CURRENT_DATE - 2) + time '10:00')::timestamptz,      2,  50, 'completed', 'paid',    'MOCKSEED0006'),\n    (7,  'sneha@example.com', 'Central Bus Stand Parking',        'F1', 'B', 5, 'KA22GH2222', ((CURRENT_DATE - 3) + time '11:00')::timestamptz,      4,  80, 'completed', 'paid',    'MOCKSEED0007'),\n    (8,  'sneha@example.com', 'Belagavi Railway Station Parking', 'F2', 'C', 5, 'KA22CD5678', ((CURRENT_DATE - 4) + time '15:00')::timestamptz,      3,  75, 'cancelled', 'pending', NULL),\n    (9,  'rahul@example.com', 'Khade Bazar Parking',              'G',  'C', 2, 'KA22AB1234', ((CURRENT_DATE - 5) + time '17:00')::timestamptz,      2,  60, 'completed', 'paid',    'MOCKSEED0009'),\n    (10, 'arjun@example.com', 'Belagavi Railway Station Parking', 'F3', 'C', 1, 'KA22EJ4321', ((CURRENT_DATE - 5) + time '09:00')::timestamptz,      8, 200, 'completed', 'paid',    'MOCKSEED0010'),\n    (11, 'sneha@example.com', 'KLS GIT Campus Parking',           'F2', 'C', 1, 'KA22CD5678', ((CURRENT_DATE - 6) + time '12:00')::timestamptz,      1,  10, 'cancelled', 'pending', NULL),\n    (12, 'rahul@example.com', 'Khade Bazar Parking',              'F3', 'B', 1, 'KA22EF1111', ((CURRENT_DATE - 8) + time '14:00')::timestamptz,      3,  90, 'completed', 'paid',    'MOCKSEED0012'),\n    (13, 'arjun@example.com', 'Central Bus Stand Parking',        'G',  'C', 3, 'KA22EJ4321', ((CURRENT_DATE - 9) + time '08:00')::timestamptz,      4,  80, 'completed', 'paid',    'MOCKSEED0013'),\n    (14, 'sneha@example.com', 'Belagavi Railway Station Parking', 'G',  'B', 4, 'KA22GH2222', ((CURRENT_DATE - 10) + time '10:00')::timestamptz,     5, 125, 'completed', 'paid',    'MOCKSEED0014'),\n    (15, 'rahul@example.com', 'Central Bus Stand Parking',        'LG', 'C', 3, 'KA22AB1234', ((CURRENT_DATE - 12) + time '18:00')::timestamptz,     2,  40, 'completed', 'paid',    'MOCKSEED0015'),\n    (16, 'arjun@example.com', 'KLS GIT Campus Parking',           'F1', 'B', 6, 'KA22EJ4321', ((CURRENT_DATE - 14) + time '09:00')::timestamptz,     3,  30, 'completed', 'paid',    'MOCKSEED0016')\n  ) AS v(n, email, loc, fl, vt, no, veh, st, hrs, amt, status, pay, ref)\n  JOIN users u ON u.email = v.email\n  JOIN parking_locations l ON l.name = v.loc\n  JOIN slots s ON s.location_id = l.id AND s.floor = v.fl AND s.vehicle_type = v.vt AND s.slot_no = v.no\n ORDER BY v.n;\n";
